const fs = require('fs');

class DataReader {
    constructor(input) {
        this.tokens = input.split(/\s+/).filter(x => x.length > 0);
        this.pos = 0;
    }

    next() {
        if (this.pos >= this.tokens.length) return null;
        return this.tokens[this.pos++];
    }

    nextToken() {
        return this.next();
    }

    nextInt() {
        return parseInt(this.nextToken(), 10);
    }

    nextLong() {
        return parseInt(this.nextToken(), 10);
    }

    readIntArray(n) {
        const result = new Array(n);
        for (let i = 0; i < n; i++) {
            result[i] = this.nextInt();
        }
        return result;
    }
}

function toYesNo(b) {
    return b ? "YES" : "NO";
}

function solve(reader, out) {
    const n = reader.nextInt();
    const k = reader.nextInt();

    const s = reader.nextToken();

    const used = new Array(n).fill(false);

    function dfs(u) {
        if (u < 0 || u >= n || used[u] || s[u] === '#') return false;
        if (s[u] === 'T') return true;
        used[u] = true;

        return dfs(u - k) || dfs(u + k);
    }

    out.push(toYesNo(dfs(s.indexOf('G'))));
}

function main() {
    let inputPath = 'input.txt';
    let outputPath = 'output.txt';

    let input;
    let out = [];

    if (process.env.ONLINE_JUDGE === undefined) {
        input = fs.readFileSync(inputPath, 'utf8');
    } else {
        input = fs.readFileSync('/dev/stdin', 'utf8');
    }

    const reader = new DataReader(input);
    solve(reader, out);

    const result = out.join('\n');

    if (process.env.ONLINE_JUDGE === undefined) {
        fs.writeFileSync(outputPath, result);
    } else {
        process.stdout.write(result);
    }
}

main();
